def stats(p):
    cells={(r,c) for r,row in enumerate(p) for c,v in enumerate(row) if v not in (6,7)}
    per=sum(sum((r+dr,c+dc) not in cells for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]) for r,c in cells)
    return len(cells),per,(max(r for r,c in cells)-min(r for r,c in cells)+1,max(c for r,c in cells)-min(c for r,c in cells)+1)
